from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal


class PromotionExpiredError(Exception):
    """Raised when an order references a promotion past its expiry."""

    def __init__(self, code):
        super().__init__(f"Promotion {code!r} has expired")
        self.code = code


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


def checkout_total(subtotal, promotion=None, now=None):
    """Return the order total. Expired promotions reject the order (provisional policy)."""
    now = now or datetime.now(tz=promotion.expires_at.tzinfo if promotion else None)
    if promotion is None:
        return subtotal
    if now >= promotion.expires_at:
        raise PromotionExpiredError(promotion.code)
    return (subtotal * (Decimal(100) - promotion.percent_off) / 100).quantize(Decimal("0.01"))
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta, timezone
from decimal import Decimal
import pytest
from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 11, 22, tzinfo=timezone.utc)
PRICE = Decimal("100.00")


def promo(delta):
    return Promotion("SAVE10", Decimal(10), NOW + delta)


def test_no_promotion():
    assert checkout_total(PRICE, None, NOW) == PRICE


def test_valid_promotion_applies():
    assert checkout_total(PRICE, promo(timedelta(days=1)), NOW) == Decimal("90.00")


def test_expired_promotion_rejects_order():
    with pytest.raises(PromotionExpiredError) as e:
        checkout_total(PRICE, promo(-timedelta(seconds=1)), NOW)
    assert e.value.code == "SAVE10"


def test_expiry_instant_counts_as_expired():
    with pytest.raises(PromotionExpiredError):
        checkout_total(PRICE, promo(timedelta(0)), NOW)
E
python -m pytest -q 2>&1 | tail -3

